# Board model

_BOARD_CACHE = {}


class Board:

    def __init__(self, board):
        self.tiles = {}           
        self.node_tiles = {}      
        self.adjacent = {}        
        self.port = {}            
        board_pips = {r: 0 for r in RESOURCES}
        for tile in board["tiles"]:
            coord = tuple(tile["tile"])
            self.tiles[coord] = (tile["resource"], tile["number"], tile["nodes"])
            if tile["resource"] is not None:
                board_pips[tile["resource"]] += PIPS.get(tile["number"], 0)
            for node in tile["nodes"]:
                self.node_tiles.setdefault(node, []).append(coord)
            for a, b in tile["edges"]:
                self.adjacent.setdefault(a, set()).add(b)
                self.adjacent.setdefault(b, set()).add(a)
        for port in board["ports"]:
            for node in port["nodes"]:
                self.port[node] = port["resource"] or "ANY"
        average = sum(board_pips.values()) / len(RESOURCES)
        self.weight = {r: RESOURCE_WEIGHT[r] * math.sqrt(average / max(board_pips[r], 1)) for r in RESOURCES}

    def node_pips(self, node, robber=None):
        """Pips per resource produced by one building on this corner."""
        pips = {}
        for coord in self.node_tiles.get(node, ()):
            resource, number, _ = self.tiles[coord]
            if resource is None or coord == robber:
                continue
            pips[resource] = pips.get(resource, 0) + PIPS.get(number, 0)
        return pips


def board_model(board):
    key = tuple((tuple(t["tile"]), t["resource"], t["number"]) for t in board["tiles"])
    model = _BOARD_CACHE.get(key)
    if model is None:
        if len(_BOARD_CACHE) > 50:
            _BOARD_CACHE.clear()
        model = _BOARD_CACHE[key] = Board(board)
    return model




def edge_key(edge):
    a, b = edge
    return (a, b) if a < b else (b, a)


class Context:
    def __init__(self, observation):
        self.obs = observation
        self.board = board_model(observation["board"])
        self.me = observation["me"]
        self.opp = observation["opponent"]
        self.robber = tuple(observation["robber_tile"])
        self.hand = dict(self.me["resources"])
        self.vps_to_win = observation.get("vps_to_win") or 7

        self.my_settlements = set(self.me["settlements"])
        self.my_cities = set(self.me["cities"])
        self.my_buildings = self.my_settlements | self.my_cities
        self.opp_buildings = set(self.opp["settlements"]) | set(self.opp["cities"])
        occupied = self.my_buildings | self.opp_buildings
        adjacent = self.board.adjacent
        self.blocked = set(occupied)  # distance rule: no building next to another
        for node in occupied:
            self.blocked |= adjacent.get(node, set())

        self.my_roads = {edge_key(e) for e in self.me["roads"]}
        self.opp_roads = {edge_key(e) for e in self.opp["roads"]}
        self.all_roads = self.my_roads | self.opp_roads
        self.network = set(self.my_buildings)  # corners my roads reach
        for a, b in self.my_roads:
            self.network.add(a)
            self.network.add(b)

        self.production = self._production(self.my_settlements, self.my_cities)
        self.opp_production = self._production(set(self.opp["settlements"]), set(self.opp["cities"]))
        self.rates = self._trade_rates()

        self.spots_now = [n for n in self.network if n not in self.blocked and n not in self.opp_buildings]
        self.spots_one_road = []
        for node in self.network:
            if node in self.opp_buildings:
                continue
            for nxt in adjacent.get(node, ()):
                if nxt not in self.blocked and nxt not in self.network and edge_key((node, nxt)) not in self.all_roads:
                    self.spots_one_road.append(nxt)
        self.best_spot_now = max((self.node_value(n) for n in self.spots_now), default=0.0)
        self.best_spot_road = max((self.node_value(n) for n in self.spots_one_road), default=0.0)
        self.targets = self._targets()


    def _production(self, settlements, cities):
        production = {r: 0.0 for r in RESOURCES}
        for node in settlements | cities:
            factor = 2 if node in cities else 1
            for resource, pips in self.board.node_pips(node, self.robber).items():
                production[resource] += factor * pips
        return production

    def _trade_rates(self):
        rates = {r: 4 for r in RESOURCES}
        for node in self.my_buildings:
            port = self.board.port.get(node)
            if port == "ANY":
                rates = {r: min(rate, 3) for r, rate in rates.items()}
        for node in self.my_buildings:
            port = self.board.port.get(node)
            if port in rates:
                rates[port] = 2
        return rates


    def node_value(self, node):
        weight = self.board.weight
        value = 0.0
        for resource, pips in self.board.node_pips(node, self.robber).items():
            missing = 1.6 if self.production[resource] == 0 else 1.0
            value += pips * weight[resource] * missing
        port = self.board.port.get(node)
        if port == "ANY":
            value += 1.0
        elif port is not None:
            value += 0.6 + 0.25 * self.production.get(port, 0)
        return value

    def city_value(self, node):
        return sum(p * self.board.weight[r] for r, p in self.board.node_pips(node, self.robber).items())


    def _targets(self):
        targets = []
        if self.my_settlements and len(self.my_cities) < 4:
            best_city = max(self.city_value(n) for n in self.my_settlements)
            targets.append((COSTS["CITY"], VP + PRODUCTION * best_city))
        if len(self.my_buildings) < 9 and len(self.my_settlements) < 5:
            if self.spots_now:
                targets.append((COSTS["SETTLEMENT"], VP + PRODUCTION * self.best_spot_now))
            elif self.spots_one_road:
                targets.append((SETTLEMENT_AND_ROAD, 0.9 * VP + PRODUCTION * self.best_spot_road))
        if self.obs.get("development_cards_left", 0) > 0:
            targets.append((COSTS["DEVELOPMENT_CARD"], DEV_CARD_EV))
        return targets

    def potential(self, hand):
        values = []
        for cost, value in self.targets:
            values.append(value * self._closeness(hand, cost))
        values.sort(reverse=True)
        total = (values[0] if values else 0.0) + (0.3 * values[1] if len(values) > 1 else 0.0)
        cards = sum(hand.values())
        total += 0.15 * cards
        if cards > 7:  # a 7 before my next turn (about 1 in 3) costs half the hand
            total -= 0.33 * (cards // 2) * 1.2
        return total

    def _closeness(self, hand, cost):
        missing = []
        surplus = 0
        for resource in RESOURCES:
            need = cost.get(resource, 0)
            have = hand.get(resource, 0)
            if have < need:
                # Per missing card: 0.35 if I never produce it, up to 0.7 if I produce lots.
                factor = 0.35 + 0.35 * min(1.0, self.production[resource] / 8.0)
                missing += [factor] * (need - have)
            else:
                surplus += (have - need) // self.rates[resource]
        if not missing:
            return 1.0
        missing.sort()  # trade away the hardest-to-get cards first
        traded = min(surplus, len(missing))
        closeness = 0.85 ** traded
        for factor in missing[traded:]:
            closeness *= factor
        return closeness


    def longest_road(self, roads):
        if len(roads) < 4:
            return len(roads)
        by_node = {}
        for a, b in roads:
            by_node.setdefault(a, []).append((a, b))
            by_node.setdefault(b, []).append((a, b))
        best = 0

        def walk(node, used, length):
            nonlocal best
            best = max(best, length)
            if node in self.opp_buildings and length > 0:
                return
            for edge in by_node.get(node, ()):
                if edge not in used:
                    used.add(edge)
                    walk(edge[1] if edge[0] == node else edge[0], used, length + 1)
                    used.discard(edge)

        for start in by_node:
            walk(start, set(), 0)
        return best

    def road_value(self, edge, free=False):
        edge = edge_key(edge)
        a, b = edge
        new = b if a in self.network else a
        adjacent = self.board.adjacent
        value = 0.0
        if new not in self.network and new not in self.opp_buildings:
            if new not in self.blocked:
                value = 3.0 + 0.25 * self.node_value(new)
            else:
                beyond = [n for n in adjacent.get(new, ()) if n not in self.blocked and n not in self.network
                          and edge_key((new, n)) not in self.all_roads]
                if beyond:
                    value = 1.0 + 0.12 * max(self.node_value(n) for n in beyond)
            if self.spots_now:
                value *= 0.4  # I already have a free spot to build on
            if len(self.my_settlements) + len(self.my_cities) >= 9:
                value *= 0.2
        # Longest road: 2 VP for the first to 5 roads in a row, beating the rival.
        current = self.me.get("longest_road_length", 0)
        after = self.longest_road(self.my_roads | {edge})
        if after > current:
            rival = self.opp.get("longest_road_length", 0)
            if self.me.get("has_longest_road"):
                value += 1.5 if after - rival <= 1 else 0.0
            else:
                value += race_bonus(max(5, rival + 1) - after, self.opp.get("has_longest_road"))
        return value


    def robber_value(self, coord, steal):
        resource, number, nodes = self.board.tiles[coord]
        if resource is None:
            block = 0.0
        else:
            pips = PIPS.get(number, 0) * self.board.weight[resource]
            opp = sum(2 if n in self.opp["cities"] else 1 for n in nodes if n in self.opp_buildings)
            mine = sum(2 if n in self.my_cities else 1 for n in nodes if n in self.my_buildings)
            block = pips * (opp - 1.5 * mine)
        if steal == "opponent" and self.opp.get("resource_cards", 0) > 0:
            block += 2.0
        return block




def _after(hand, cost=None, gain=None):
    new = dict(hand)
    for resource, count in (cost or {}).items():
        new[resource] = new.get(resource, 0) - count
    for resource, count in (gain or {}).items():
        new[resource] = new.get(resource, 0) + count
    return new


def _initial_settlement(ctx, node):
    value = ctx.node_value(node)
    # Diversity: covering more resource types early makes every build reachable.
    value += 0.6 * len(ctx.board.node_pips(node))
    # Leave room to expand: the best corner two steps away.
    adjacent = ctx.board.adjacent
    reach = [m for n in adjacent.get(node, ()) for m in adjacent.get(n, ())
             if m != node and m not in ctx.blocked and m not in adjacent.get(node, ())]
    value += 0.1 * max((ctx.node_value(m) for m in reach), default=0.0)
    return value


def _initial_road(ctx, edge):
    a, b = edge_key(edge)
    # The road starts at the settlement that has no road yet.
    new = b if a in ctx.network else a
    if a in ctx.network and b in ctx.network:
        new = b if a in ctx.my_buildings else a
    beyond = [n for n in ctx.board.adjacent.get(new, ()) if n not in ctx.blocked]
    return max((ctx.node_value(n) for n in beyond), default=0.0)


def _knight_value(ctx):
    value = 1.0
    if ctx.robber in ctx.board.tiles:
        resource, number, nodes = ctx.board.tiles[ctx.robber]
        if resource is not None:
            mine = sum(2 if n in ctx.my_cities else 1 for n in nodes if n in ctx.my_buildings)
            value += 0.5 * mine * PIPS.get(number, 0) * ctx.board.weight[resource]
    best_block = max((ctx.robber_value(c, "opponent") for c in ctx.board.tiles if c != ctx.robber), default=0.0)
    value += 0.15 * max(best_block, 0.0)
    played = ctx.me["played_development_cards"].get("KNIGHT", 0) + 1
    rival = ctx.opp["played_development_cards"].get("KNIGHT", 0)
    if ctx.me.get("has_largest_army"):
        value += 1.5 if played - rival <= 1 else 0.0
    else:
        value += race_bonus(max(3, rival + 1) - played, ctx.opp.get("has_largest_army"))
    return value


def _dev_card_value(ctx):
    value = DEV_CARD_EV
    if not ctx.me.get("has_largest_army"):
        knights = ctx.me["played_development_cards"].get("KNIGHT", 0)
        knights += ctx.me["development_cards_in_hand"].get("KNIGHT", 0)
        rival = ctx.opp["played_development_cards"].get("KNIGHT", 0)
        needed = max(3, rival + 1) - (knights + 1)
        value += (14 / 25) * 0.6 * race_bonus(needed, ctx.opp.get("has_largest_army"))
    return value


def race_bonus(still_needed, rival_holds_it):

    steal = 1.5 if rival_holds_it else 1.0
    if still_needed <= 0:
        return 2 * VP * steal
    if still_needed > 3:
        return 0.0
    return 2 * VP * RACE * steal / (still_needed + 1)


def score_action(ctx, action):
    """Heuristic utility of one legal action, relative to ending the turn (0)."""
    kind = action["type"]
    phase = ctx.obs["phase"]
    hand = ctx.hand
    base = ctx.potential(hand)

    def delta(new_hand):
        return KAPPA * (ctx.potential(new_hand) - base)

    if phase == "initial_placement":
        if kind == "BUILD_SETTLEMENT":
            return _initial_settlement(ctx, action["node"])
        if kind == "BUILD_ROAD":
            return _initial_road(ctx, action["edge"])
        return 0.0

    if kind == "END_TURN":
        return 0.0
    if kind == "ROLL":
        return 0.5
    if kind == "MOVE_ROBBER":
        return ctx.robber_value(tuple(action["tile"]), action.get("steal_from"))
    if kind == "BUILD_CITY":
        win = VP * 10 if ctx.me["victory_points"] + 1 >= ctx.vps_to_win else 0.0
        return VP + win + PRODUCTION * ctx.city_value(action["node"]) + delta(_after(hand, COSTS["CITY"]))
    if kind == "BUILD_SETTLEMENT":
        win = VP * 10 if ctx.me["victory_points"] + 1 >= ctx.vps_to_win else 0.0
        return VP + win + PRODUCTION * ctx.node_value(action["node"]) + delta(_after(hand, COSTS["SETTLEMENT"]))
    if kind == "BUILD_ROAD":
        if phase == "free_roads":
            return ctx.road_value(action["edge"], free=True)
        value = ctx.road_value(action["edge"])
        if value >= 2 * VP and ctx.me["victory_points"] + 2 >= ctx.vps_to_win:
            value += VP * 10
        return value + delta(_after(hand, COSTS["ROAD"]))
    if kind == "BUY_DEVELOPMENT_CARD":
        return _dev_card_value(ctx) + delta(_after(hand, COSTS["DEVELOPMENT_CARD"]))
    if kind == "MARITIME_TRADE":
        new_hand = _after(hand, {action["give"]: action["give_count"]}, {action["receive"]: 1})
        return delta(new_hand) - 0.05
    if kind == "PLAY_KNIGHT_CARD":
        return _knight_value(ctx)
    if kind == "PLAY_YEAR_OF_PLENTY":
        gain = {}
        for resource in action["resources"]:
            gain[resource] = gain.get(resource, 0) + 1
        return delta(_after(hand, None, gain)) + 0.5 * len(action["resources"])
    if kind == "PLAY_MONOPOLY":
        resource = action["resource"]
        total = sum(ctx.opp_production.values()) or 1.0
        share = (ctx.opp_production[resource] + 1.0) / (total + 5.0)
        expected = int(round(ctx.opp.get("resource_cards", 0) * share))
        return delta(_after(hand, None, {resource: expected})) + 0.3 * expected
    if kind == "PLAY_ROAD_BUILDING":
        roads = sorted((ctx.road_value(e) for e in _candidate_edges(ctx)), reverse=True)
        return 0.5 + sum(roads[:2])
    return 0.0


def _candidate_edges(ctx):
    edges = []
    for node in ctx.network:
        if node in ctx.opp_buildings:
            continue
        for nxt in ctx.board.adjacent.get(node, ()):
            edge = edge_key((node, nxt))
            if edge not in ctx.all_roads:
                edges.append(edge)
    return edges


def heuristic_scores(observation):
    ctx = Context(observation)
    return {action["id"]: score_action(ctx, action) for action in observation["actions"]}




def act(observation):
    """Called at each decision. Returns {"action": <id of a legal action>}."""
    actions = observation["actions"]
    try:
        scores = heuristic_scores(observation)
        if BETA and Q_TABLE:
            advantage = learned_advantage(observation)
            for action in actions:
                scores[action["id"]] += BETA * advantage.get(action["type"], 0.0)
        best = max(actions, key=lambda a: (scores[a["id"]], -a["id"]))
        return {"action": best["id"]}
    except Exception:
        return {"action": _safe_fallback(observation)}


def _safe_fallback(observation):
    actions = observation["actions"]
    for kind in ("BUILD_CITY", "BUILD_SETTLEMENT", "ROLL", "END_TURN"):
        for action in actions:
            if action["type"] == kind:
                return action["id"]
    return actions[0]["id"]




def _bucket(value, edges):
    for index, edge in enumerate(edges):
        if value < edge:
            return index
    return len(edges)


def state_features(observation):
    """Small, deterministic abstraction of the state (the MDP state for Q-learning).

    (phase, my VP, rival VP, what I can afford, production strength, game stage)
    """
    me, opp = observation["me"], observation["opponent"]
    hand = me["resources"]

    def affordable(cost):
        return all(hand.get(r, 0) >= n for r, n in cost.items())

    if affordable(COSTS["CITY"]) and me["settlements"]:
        can = "city"
    elif affordable(COSTS["SETTLEMENT"]):
        can = "settlement"
    elif affordable(COSTS["DEVELOPMENT_CARD"]):
        can = "dev"
    elif affordable(COSTS["ROAD"]):
        can = "road"
    else:
        can = "none"
    cards = sum(hand.values())
    return (
        observation["phase"],
        min(me["victory_points"], 6),
        min(opp["visible_victory_points"], 6),
        can,
        _bucket(cards, (3, 6, 8)),
        _bucket(observation.get("round", 0), (15, 35, 60)),
    )


def q_key(features, action_type):
    return f"{features}|{action_type}"


def learned_advantage(observation):
    """Learned Q of each legal action type minus their average (trusted entries only)."""
    features = state_features(observation)
    values = {}
    for kind in {a["type"] for a in observation["actions"]}:
        key = q_key(features, kind)
        if key in Q_TABLE:
            values[kind] = Q_TABLE[key]
    if len(values) < 2:
        return {}
    mean = sum(values.values()) / len(values)
    return {kind: value - mean for kind, value in values.items()}


def action_value(observation, action_id):
    """Estimated value of an action: learned Q(s, type) when trusted, else the heuristic.

    The heuristic score is scaled to the same units as Q (victory points), so both
    can be compared.
    """
    action = next(a for a in observation["actions"] if a["id"] == action_id)
    key = q_key(state_features(observation), action["type"])
    if key in Q_TABLE:
        return float(Q_TABLE[key])
    ctx = Context(observation)
    value = score_action(ctx, action) / VP
    return float(value) if math.isfinite(value) else 0.0


def q_update(q, reward, best_next_q, alpha, gamma):
    """One Q-learning update. Returns the new value for Q(s, a)."""
    target = reward + gamma * best_next_q
    return q + alpha * (target - q)


def heuristic_policy(observation):
    """Baseline: the action with the best one-step heuristic utility. Returns its id."""
    actions = observation["actions"]
    try:
        scores = heuristic_scores(observation)
        return max(actions, key=lambda a: (scores[a["id"]], -a["id"]))["id"]
    except Exception:
        return _safe_fallback(observation)
